export const canonical39RetiredRecoveryDatabaseBytes = (scenario: Canonical39RetiredRecoveryScenario): Buffer => {
  const fixture = canonical39RetiredRecoveryFixtures[scenario];
  const recipe = readFileSync(new URL("./canonical39-retired-recovery-generator.original.ts.txt", import.meta.url));
  if (createHash("sha256").update(recipe).digest("hex") !== fixture.generatorSha256) {
    throw new Error("Canonical39 retired recovery recipe changed.");
  }
  const bytes = gunzipSync(Buffer.from(images[scenario], "base64"), { maxOutputLength: fixture.databaseBytes });
  if (bytes.length !== fixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== fixture.databaseSha256) {
    throw new Error("Canonical39 retired recovery image changed.");
  }
  return bytes;
};
